	const pendingLogChunks = [];
	const uiLogger = {
		log: (...args) => {
			const text = args.map(String).join(' ');
			logger.log(text);
			pendingLogChunks.push(text);
		},
		warn: (...args) => {
			const text = args.map(String).join(' ');
			logger.warn(text);
			pendingLogChunks.push(text);
		},
		error: (...args) => {
			const text = args.map(String).join(' ');
			logger.error ? logger.error(text) : logger.warn(text);
			pendingLogChunks.push(text);
		},
	};

